/**
 * Computes the pair of indices to compare during a bitonic flip operation.
 *
 * In a flip operation, elements are compared at mirrored positions within each block.
 * For a block of height `h`, element at position `i` is compared with element at
 * position `h - 1 - i` within the same block.
 *
 * @function
 * @private
 * @param {Node<uint>} index - The compute thread's invocation index.
 * @param {Node<uint>} blockHeight - The height of the block within which elements are being swapped.
 * @returns {Node<uvec2>} A pair of indices (x, y) where x < y, representing the two elements to compare.
 */
export const getBitonicFlipIndices: any;
/**
 * Computes the pair of indices to compare during a bitonic disperse operation.
 *
 * In a disperse operation, elements are compared at a fixed distance (half the swap span)
 * apart. This operation merges bitonic sequences into sorted sequences.
 *
 * @function
 * @private
 * @param {Node<uint>} index - The compute thread's invocation index.
 * @param {Node<uint>} swapSpan - The span over which elements are being compared (distance * 2).
 * @returns {Node<uvec2>} A pair of indices (x, y) where x < y, representing the two elements to compare.
 */
export const getBitonicDisperseIndices: any;
/**
 * @class
 * @short Stable GPU bitonic sort for uvec2 key/id pairs with WebGPU and WebGL paths; used by culling and sims.
 * @category Compute
 * @tags WebGPU
 */
export class ComputeBitonicSort {
    /**
     * GPU-accelerated parallel bitonic sort for Three.js TSL compute shaders.
     *
     * ComputeBitonicSort provides an efficient O(n log²n) parallel sorting algorithm that runs
     * entirely on the GPU. It's designed for sorting large arrays of key-value pairs where
     * deterministic, stable ordering is required. It is used in SPH, PBF, Boids, IndirectBatchedMesh, ComputeInstanceCulling.
     *
     * ## Features
     *
     * - **Fully GPU-accelerated**: All sorting operations execute as compute shaders
     * - **Stable sorting**: Elements with equal keys maintain their relative order via tie-breaker IDs
     * - **Deterministic**: Produces identical results across frames and devices
     * - **Dual-backend support**: Optimized path for WebGPU, fallback for WebGL
     * - **Workgroup optimization**: Uses shared memory for efficient local sorting (WebGPU)
     * - **Bounds-safe**: Handles non-power-of-two counts with sentinel values
     *
     * ## Usage
     *
     * ```javascript
     * import { instancedArray } from 'three/tsl';
     * import { ComputeBitonicSort } from './ComputeBitonicSort.js';
     *
     * // Create a buffer of uvec2 pairs: (sortKey, stableId)
     * const count = 1024;
     * const dataBuffer = instancedArray( count, 'uvec2' );
     *
     * // Initialize the sorter
     * const sorter = new ComputeBitonicSort( dataBuffer, { workgroupSize: 64 } );
     *
     * // In your render loop:
     * sorter.compute( renderer ); // Full sort in one call
     *
     * // Or for amortized sorting across frames:
     * sorter.computeStep( renderer ); // One step per frame
     * ```
     *
     * ## Data Format
     *
     * The data buffer must contain `uvec2` elements where:
     * - **x**: The primary sort key (e.g., spatial hash, distance, priority)
     * - **y**: A unique stable ID to break ties deterministically
     *
     * Elements are sorted in ascending order by (x, y) lexicographically.
     *
     * ## Performance Considerations
     *
     * - Buffer count should ideally be a power of 2 for optimal performance
     * - Larger workgroup sizes (64-256) typically perform better on modern GPUs
     * - The `compute()` method executes all steps synchronously; use `computeStep()`
     *   for amortized sorting across multiple frames
     *
     *
     * @param {StorageBufferNode} dataBuffer - The storage buffer containing uvec2 elements to sort.
     *   Each element should be a uvec2 where x is the sort key and y is a stable tie-breaker ID.
     * @param {Object} [options={}] - Configuration options.
     * @param {number} [options.workgroupSize=64] - The workgroup size for compute shaders.
     *   Must be a power of 2. Larger values (64-256) typically perform better but are limited
     *   by GPU capabilities. Will be clamped to valid ranges automatically.
     * @param {boolean} [options.ascending=true] - Sort direction. If true (default), sorts in
     *   ascending order (smallest keys first). If false, sorts in descending order (largest keys first).
     *
     * @example
     * // Ascending sort (default)
     * const sorter = new ComputeBitonicSort( dataBuffer, { workgroupSize: 128 } );
     *
     * @example
     * // Descending sort (for front-to-back rendering)
     * const sorter = new ComputeBitonicSort( dataBuffer, { workgroupSize: 128, ascending: false } );
     */
    constructor(dataBuffer: StorageBufferNode, options?: {
        workgroupSize?: number;
        ascending?: boolean;
    });
    /**
     * The storage buffer containing the data to be sorted.
     * Elements are uvec2 pairs: (sortKey, stableId).
     * @type {StorageBufferNode}
     */
    dataBuffer: StorageBufferNode;
    /**
     * The number of elements in the data buffer.
     * @type {number}
     */
    count: number;
    /**
     * The number of thread groups to dispatch for compute operations.
     * Each thread handles one comparison, so dispatchSize = count / 2.
     * @type {number}
     */
    dispatchSize: number;
    /**
     * The number of threads per workgroup.
     * Determines how many elements can be sorted in local shared memory.
     * Each workgroup sorts 2 * workgroupSize elements locally.
     * @type {number}
     */
    workgroupSize: number;
    /**
     * Sort direction. If true (default), sorts ascending (smallest keys first).
     * If false, sorts descending (largest keys first).
     * @type {boolean}
     */
    ascending: boolean;
    /**
     * Force global-only sorting (no local workgroup optimization).
     * When true, behaves like WebGL path even on WebGPU.
     * Useful for debugging or when local sorting causes issues.
     * @type {boolean}
     */
    globalOnly: boolean;
    /**
     * The comparator function based on sort direction.
     * @private
     * @type {Function}
     */
    private _compare;
    /**
     * Workgroup-scoped shared memory buffer for local sorting operations.
     * Holds 2 * workgroupSize elements during local sort phases.
     * Only initialized for WebGPU backends.
     * @type {WorkgroupInfoNode|null}
     */
    localStorage: WorkgroupInfoNode | null;
    /**
     * Temporary array used for internal operations.
     * @private
     * @type {Uint32Array}
     */
    private _tempArray;
    /**
     * Temporary storage buffer for ping-pong operations during global swaps.
     * Global operations read from one buffer and write to the other to avoid
     * read-after-write hazards.
     * @type {StorageBufferNode}
     */
    tempBuffer: StorageBufferNode;
    /**
     * Storage buffer containing algorithm state: [stepType, currentSwapSpan, maxSwapSpan].
     * Used to coordinate multi-dispatch sorting operations.
     * @type {StorageBufferNode}
     */
    infoStorage: StorageBufferNode;
    /**
     * Total number of distinct swap operations (flips + disperses) in a complete sort.
     * For n elements: (log2(n) * (log2(n) + 1)) / 2
     * @type {number}
     */
    swapOpCount: number;
    /**
     * Total number of compute dispatches needed for a complete sort.
     * Depends on whether local sorting is available (WebGPU) or not (WebGL).
     * @type {number}
     */
    stepCount: number;
    /**
     * Name of the buffer currently being read from ('Data' or 'Temp').
     * Used for ping-pong buffer management during global operations.
     * @type {string}
     */
    readBufferName: string;
    /**
     * Compute nodes for global flip operations, keyed by source buffer name.
     * @type {Object<string, ComputeNode>}
     */
    flipGlobalNodes: {
        [x: string]: ComputeNode;
    };
    /**
     * Compute nodes for global disperse operations, keyed by source buffer name.
     * @type {Object<string, ComputeNode>}
     */
    disperseGlobalNodes: {
        [x: string]: ComputeNode;
    };
    /**
     * Compute node for complete local sorting (flip + all disperse stages).
     * Only available on WebGPU backends.
     * @type {ComputeNode|null}
     */
    swapLocalFn: ComputeNode | null;
    /**
     * Compute nodes for local disperse operations, keyed by source buffer name.
     * Only available on WebGPU backends.
     * @type {Object<string, ComputeNode>|null}
     */
    disperseLocalNodes: {
        [x: string]: ComputeNode;
    } | null;
    /**
     * Compute node that advances the algorithm state to the next step.
     * @type {ComputeNode|null}
     */
    setAlgoFn: ComputeNode | null;
    /**
     * Compute node that copies data from temp buffer back to data buffer.
     * Used to ensure results end up in the original data buffer.
     * @type {ComputeNode}
     */
    alignFn: ComputeNode;
    /**
     * Compute node that resets algorithm state for a new sort operation.
     * @type {ComputeNode|null}
     */
    resetFn: ComputeNode | null;
    /**
     * Current dispatch index within the sort operation (0 to stepCount - 1).
     * @type {number}
     */
    currentDispatch: number;
    /**
     * Number of remaining global operations before switching to local disperse.
     * Used for WebGPU path state management.
     * @type {number}
     */
    globalOpsRemaining: number;
    /**
     * Total global operations in the current span.
     * Increments as we process larger swap spans.
     * @type {number}
     */
    globalOpsInSpan: number;
    /**
     * Whether the sorter has been initialized with a renderer.
     * @type {boolean}
     */
    initialized: boolean;
    /**
     * Whether the current backend is WebGL (lacks workgroup shared memory).
     * @type {boolean}
     */
    isWebGL: boolean;
    /**
     * Initializes the sorter for the given renderer.
     *
     * This method detects the backend type (WebGL vs WebGPU) and creates the
     * appropriate compute shaders. Must be called before sorting, but is
     * automatically invoked by `compute()` and `computeStep()` if needed.
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     */
    init(renderer: WebGPURenderer): void;
    useGlobalOnly: boolean;
    webglState: any;
    /**
     * Calculates the total number of swap operations in a bitonic sort.
     *
     * @private
     * @returns {number} The number of distinct swap operations: (log2(n) * (log2(n) + 1)) / 2
     */
    private _getSwapOpCount;
    /**
     * Calculates the number of compute dispatches needed for a complete sort.
     *
     * For WebGL (global-only): Same as swap operation count.
     * For WebGPU (local + global): Fewer dispatches due to local sorting optimization.
     *
     * @private
     * @returns {number} The total number of compute dispatches required.
     */
    private _getStepCount;
    /**
     * Performs a compare-and-swap operation in global memory.
     *
     * Reads two elements from the source buffer, compares them, and writes
     * them in sorted order to the destination buffer.
     *
     * @private
     * @param {Node<uint>} idxBefore - Index of the first element.
     * @param {Node<uint>} idxAfter - Index of the second element.
     * @param {StorageBufferNode} dataBuffer - Source buffer to read from.
     * @param {StorageBufferNode} tempBuffer - Destination buffer to write to.
     */
    private _globalCompareAndSwapTSL;
    /**
     * Performs a compare-and-swap operation in workgroup shared memory.
     *
     * Reads two elements from local storage, compares them, and writes
     * them back in sorted order.
     *
     * @private
     * @param {Node<uint>} idxBefore - Local index of the first element.
     * @param {Node<uint>} idxAfter - Local index of the second element.
     */
    private _localCompareAndSwapTSL;
    /**
     * Creates a compute shader for global disperse operations.
     *
     * @private
     * @param {StorageBufferNode} readBuffer - Buffer to read elements from.
     * @param {StorageBufferNode} writeBuffer - Buffer to write sorted elements to.
     * @returns {ComputeNode} The disperse compute shader.
     */
    private _getDisperseGlobal;
    /**
     * Creates a compute shader for global flip operations.
     *
     * @private
     * @param {StorageBufferNode} readBuffer - Buffer to read elements from.
     * @param {StorageBufferNode} writeBuffer - Buffer to write sorted elements to.
     * @returns {ComputeNode} The flip compute shader.
     */
    private _getFlipGlobal;
    /**
     * Creates the compute shader for complete local sorting.
     *
     * This shader performs a full bitonic sort on elements within a single workgroup
     * using shared memory. Each workgroup independently sorts 2 * workgroupSize elements.
     *
     * The algorithm:
     * 1. Load elements from global memory into shared memory (with OOB sentinel handling)
     * 2. For each block size k = 2, 4, 8, ..., localSize:
     *    - Perform flip operation with block height k
     *    - For each disperse span j = k/2, k/4, ..., 1:
     *      - Perform disperse operation
     * 3. Write sorted elements back to global memory
     *
     * @private
     * @returns {ComputeNode} The local swap compute shader.
     */
    private _getSwapLocal;
    /**
     * Creates the compute shader for local disperse operations.
     *
     * This shader performs disperse-only stages in shared memory, used after
     * a global flip to complete the merge operation locally.
     *
     * @private
     * @param {StorageBufferNode} readWriteBuffer - Buffer to read from and write to.
     * @returns {ComputeNode} The local disperse compute shader.
     */
    private _getDisperseLocal;
    /**
     * Creates the compute shader that resets algorithm state for a new sort.
     *
     * @private
     * @returns {ComputeNode} The reset compute shader.
     */
    private _getResetFn;
    /**
     * Creates the compute shader that copies temp buffer back to data buffer.
     *
     * Used to ensure the final sorted result is in the original data buffer
     * after an odd number of global operations.
     *
     * @private
     * @returns {ComputeNode} The alignment compute shader.
     */
    private _getAlignFn;
    /**
     * Creates the compute shader that advances algorithm state to the next step.
     *
     * Determines the next operation type (flip/disperse, local/global) and
     * updates the swap span accordingly.
     *
     * @private
     * @returns {ComputeNode} The state advancement compute shader.
     */
    private _getSetAlgoFn;
    /**
     * Executes a single step of the bitonic sort.
     *
     * Call this method repeatedly (once per frame) to amortize sorting cost
     * over multiple frames. A complete sort requires `stepCount` calls.
     *
     * The method automatically:
     * - Initializes on first call
     * - Advances through flip/disperse stages
     * - Handles buffer ping-ponging
     * - Resets state when sort completes
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     *
     * @example
     * // Amortized sorting - one step per frame
     * function animate() {
     *   sorter.computeStep( renderer );
     *   renderer.render( scene, camera );
     * }
     */
    computeStep(renderer: WebGPURenderer): void;
    /**
     * Executes a complete bitonic sort in a single call.
     *
     * This method runs all sorting steps synchronously, which may cause
     * frame drops for large arrays. For real-time applications, consider
     * using `computeStep()` to spread the work across multiple frames.
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     *
     * @example
     * // Complete sort in one frame
     * sorter.compute( renderer );
     * // Data buffer is now fully sorted
     */
    compute(renderer: WebGPURenderer): void;
    /**
     * Disposes of GPU resources held by this sorter.
     *
     * Call this method when the sorter is no longer needed to free GPU memory.
     * After disposal, the sorter should not be used.
     */
    dispose(): void;
}
